        assert_eq!(rows[0].0.source(), &SearchMatchSource::Name);
        assert_eq!(db.get_funders_by_text_search_score(&request("zzzzzz", 2, 0.0)).await.unwrap().len(), 2);
        assert_eq!(db.get_funders_by_text_search_score(&request("West Midlands", 1, 1.0)).await.unwrap().len(), 1);
        let boundary = sqlx::query!("SELECT word_similarity('West Mid', 'West Midlands') AS score").fetch_one(&pool).await?.score.unwrap();
        assert!(boundary > 0.0 && boundary < 1.0);
        assert_eq!(db.get_funders_by_text_search_score(&request("West Mid", 2, boundary)).await.unwrap().len(), 2);
        let after = sqlx::query!("SELECT current_setting('pg_trgm.word_similarity_threshold') AS threshold").fetch_one(&pool).await?.threshold;
