#[cfg(test)]
mod threshold_scoring {
    use sqlx::PgPool;
    use crate::{domain::{models::entity_search::EntitySearchRequest, repositories::parliament_member_repository::ParliamentMemberRepo}, outbound::postgres::ExposedDatabase};

    #[sqlx::test(migrations = "../db/migrations", fixtures("../../../../db/fixtures/add_members.sql"))]
    async fn inclusive_thresholds_are_local(pool: PgPool) -> sqlx::Result<()> {
        let pool = sqlx::postgres::PgPoolOptions::new().max_connections(1).connect_with(pool.connect_options().as_ref().clone()).await?;
        let initial = sqlx::query!("SELECT current_setting('pg_trgm.word_similarity_threshold') AS threshold").fetch_one(&pool).await?.threshold;
        let db = ExposedDatabase::from(pool.clone());
        let boundary = sqlx::query!("SELECT word_similarity('John McD', 'John McDonnell') AS score").fetch_one(&pool).await?.score.unwrap();
        assert!(boundary > 0.0 && boundary < 1.0);
        for (term, threshold, count) in [("zzzzzz", 0.0, 2), ("John McDonnell", 1.0, 1), ("John McD", boundary, 1)] {
